const totals = {};
for (const line of inputs.lines) {
  if (!line.startsWith('INV')) continue;
  const [number, customer, amount] = line.split(';');
  totals[customer] = (totals[customer] ?? 0) + Number(amount);
}
const customers = Object.keys(totals).sort();
return {
  totals,
  summary: customers.map(c => `${c}: ${totals[c].toFixed(2)}`).join(', ')
};
